const valid=record&&(!record.warrantyStart||validDate(record.warrantyStart))&&(!record.warrantyEnd||validDate(record.warrantyEnd))&&(!record.warrantyStart||!record.warrantyEnd||record.warrantyStart<=record.warrantyEnd);
