const d=rows.find(d=>d.id===state.selected);if(!d)return;const editor=$('#yw-operation-editor');if(d.stage==='生产采购'){renderProductionEditor(d,editor);return;}editor.innerHTML=reviewProblem(d)+reviewMedia(d)+previousRepairs(d)+`<div class="review-problem"><small>审核处理方法 / 工程资料</small><p>${esc(d.review?.method||'待补充')}</p><p>${esc(d.engineering?.orderNumber||'无需物料下单')} · ${esc(d.engineering?.items||'')}</p><p>下单组：${esc(d.engineering?.orderGroup||'待补充')} · 下单人：${esc(d.engineering?.engineer||'待补充')} · 下单计划完成：${esc(d.engineering?.plannedAt||'待补充')} · 下单实际完成：${esc(d.engineering?.completedAt||'待补充')}</p></div>`+reviewHistory(d);
